"""Phase detection and metric aggregation over a parsed Session.

A "phase" is a contiguous run of turns starting with a user prompt that introduces a
slash command (or session start) and ending just before the next slash command.

Each phase carries:
  - title (slash command or "Session boot")
  - start/end timestamp
  - duration_seconds
  - tool / agent / mcp counts
  - file paths touched (Edit/Write/Read inputs)
  - human-in-loop user messages (mid-phase user prompts that are not slash commands)
  - per-turn token totals
"""

from __future__ import annotations

import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import datetime

from harness.analyse.parser import Session, Turn

_AGENT_TOOL_NAMES = {"Agent", "Task"}
_HOOK_PREFIXES = ("session", "hook")


@dataclass
class HumanIntervention:
    timestamp: datetime
    text: str  # truncated to ~600 chars for the report


@dataclass
class PhaseMetrics:
    tool_counts: Counter = field(default_factory=Counter)
    subagent_calls: Counter = field(default_factory=Counter)  # by agent name (best-effort)
    mcp_calls: Counter = field(default_factory=Counter)
    files_written: list[str] = field(default_factory=list)
    files_edited: list[str] = field(default_factory=list)
    files_read: list[str] = field(default_factory=list)
    bash_commands: int = 0
    input_tokens: int = 0
    output_tokens: int = 0
    cache_create_tokens: int = 0
    cache_read_tokens: int = 0
    # Sub-step walkthrough: which `.claude/skills/<cmd>/steps/<NN>-*.md` files
    # the agent actually loaded, in order, deduplicated.
    steps_walked: list[str] = field(default_factory=list)
    # Artefacts produced or updated under docs/* and docs/state/, grouped
    # by category for the dashboard "Artefacts" section.
    artefacts: dict[str, list[str]] = field(default_factory=dict)


@dataclass
class Phase:
    index: int
    title: str
    slash_command: str | None
    start: datetime
    end: datetime
    turns: list[Turn]
    interventions: list[HumanIntervention]
    metrics: PhaseMetrics

    @property
    def duration_seconds(self) -> int:
        return int((self.end - self.start).total_seconds())


@dataclass
class SessionAnalysis:
    session: Session
    phases: list[Phase]
    total_metrics: PhaseMetrics
    total_cost_usd: float


# Sonnet 4.6 rate card ($/M tokens). Used to estimate cost when the model on
# every turn is sonnet — fall back to 0 otherwise.
_SONNET_46_RATE = {
    "input": 3.00,
    "output": 15.00,
    "cache_create": 3.75,
    "cache_read": 0.30,
}


def analyse(session: Session) -> SessionAnalysis:
    phases = _split_phases(session.turns)
    for ph in phases:
        ph.metrics = _aggregate(ph.turns)
    total = _aggregate(session.turns)
    cost = _estimate_cost(session.turns, total)
    return SessionAnalysis(
        session=session,
        phases=phases,
        total_metrics=total,
        total_cost_usd=cost,
    )


_HUMAN_ANSWER_PREFIX_RE = re.compile(
    r"^User has answered your questions:\s*", re.IGNORECASE
)
_HUMAN_ANSWER_TAIL_RE = re.compile(
    r"\.\s*You can now continue with the user'?s answers in mind\.?\s*$",
    re.IGNORECASE,
)


def _clean_human_answer(raw: str) -> str:
    """Strip Claude Code's boilerplate around an AskUserQuestion answer.

    Input shape:
        `User has answered your questions: "<question>"="<answer>". You can now
        continue with the user's answers in mind.`

    Output: just `"<question>"="<answer>"` — the human-meaningful content.
    Multi-question answers are joined by `; `.
    """
    text = raw.strip()
    text = _HUMAN_ANSWER_PREFIX_RE.sub("", text)
    text = _HUMAN_ANSWER_TAIL_RE.sub("", text)
    return text.strip()


def _split_phases(turns: list[Turn]) -> list[Phase]:
    """A new phase starts on every user turn whose `slash_command` is set, OR on
    the first turn of the session. The first phase covers session boot through
    the first slash command (so SessionStart hook + /model land in Phase 0)."""
    if not turns:
        return []
    phase_starts: list[int] = []  # indexes into turns where a phase begins
    for i, t in enumerate(turns):
        if i == 0:
            phase_starts.append(0)
            continue
        if t.role == "user" and t.slash_command:
            phase_starts.append(i)

    phases: list[Phase] = []
    for k, start_idx in enumerate(phase_starts):
        end_idx = phase_starts[k + 1] - 1 if k + 1 < len(phase_starts) else len(turns) - 1
        slice_ = turns[start_idx:end_idx + 1]
        first = slice_[0]
        last = slice_[-1]
        cmd = first.slash_command if first.role == "user" else None
        args = first.command_args if first.role == "user" else None
        title = (f"/{cmd} {args}" if args else f"/{cmd}") if cmd else "Session boot"

        # Human interventions = user turns inside this phase that are NOT the
        # initial slash-command turn AND not synthetic Claude Code messages
        # (tool results, system reminders, command-name wrappers, meta turns).
        # EXCEPTION: AskUserQuestion answers (`is_human_answer=True`) are
        # tool_result-shaped but represent real human input — surface them.
        interventions: list[HumanIntervention] = []
        for j, tt in enumerate(slice_):
            if tt.role != "user":
                continue
            if j == 0:
                continue  # initial command
            if tt.is_human_answer:
                # AskUserQuestion answer — keep, but trim the boilerplate prefix
                # for readability.
                cleaned = _clean_human_answer(tt.text or "")
                if cleaned:
                    interventions.append(HumanIntervention(
                        timestamp=tt.timestamp,
                        text=cleaned[:600],
                    ))
                continue
            if tt.is_tool_result_only:
                continue  # synthetic tool-result, not human input
            if tt.is_meta:
                continue  # framework-injected (e.g. isMeta=true)
            if tt.slash_command:
                continue  # another slash command — counts as new phase, not intervention
            text = (tt.text or "").strip()
            if not text:
                continue
            # Legacy tag-wrapped synthetic content (older Claude Code versions).
            if "<tool_use_result>" in text or "<tool-result>" in text:
                continue
            if text.startswith("<system-reminder>"):
                continue
            # Claude Code's tool-interrupt sentinel — not user feedback, just an
            # interrupt event recorded as a user turn.
            if text.strip() == "[Request interrupted by user for tool use]":
                continue
            # Synthetic system-injected blocks: <command-name>, <local-command-stdout>,
            # <bash-stdout>, <command-stdout>, <ide_*>, <user-prompt-submit-hook>, etc.
            # If the visible text after stripping wrapper tags is empty, it's not a
            # human intervention.
            stripped = re.sub(r"<[^>]+>[\s\S]*?</[^>]+>", "", text)
            stripped = re.sub(r"<[^>]+/?>", "", stripped).strip()
            if not stripped:
                continue
            interventions.append(HumanIntervention(
                timestamp=tt.timestamp,
                text=stripped[:600],
            ))

        phases.append(Phase(
            index=k,
            title=title,
            slash_command=cmd,
            start=first.timestamp,
            end=last.timestamp,
            turns=slice_,
            interventions=interventions,
            metrics=PhaseMetrics(),  # filled below
        ))
    return phases


def _aggregate(turns: list[Turn]) -> PhaseMetrics:
    m = PhaseMetrics()
    for t in turns:
        if t.role != "assistant":
            continue
        m.input_tokens += t.usage.input_tokens
        m.output_tokens += t.usage.output_tokens
        m.cache_create_tokens += t.usage.cache_creation_input_tokens
        m.cache_read_tokens += t.usage.cache_read_input_tokens

        for tu in t.tool_uses:
            m.tool_counts[tu.name] += 1
            if tu.name == "Bash":
                m.bash_commands += 1
            if tu.name in _AGENT_TOOL_NAMES:
                # Best-effort subagent name detection — `subagent_type` is the
                # canonical field (Task tool); legacy may use `agent_type`.
                agent_name = (tu.input or {}).get("subagent_type") \
                    or (tu.input or {}).get("agent_type") \
                    or (tu.input or {}).get("description") \
                    or "(unnamed)"
                m.subagent_calls[agent_name] += 1
            if tu.name.startswith("mcp__"):
                m.mcp_calls[tu.name] += 1
            if tu.name in {"Edit", "MultiEdit"}:
                fp = (tu.input or {}).get("file_path")
                if fp and fp not in m.files_edited:
                    m.files_edited.append(fp)
            if tu.name == "Write":
                fp = (tu.input or {}).get("file_path")
                if fp and fp not in m.files_written:
                    m.files_written.append(fp)
            if tu.name == "Read":
                fp = (tu.input or {}).get("file_path")
                if fp and fp not in m.files_read:
                    m.files_read.append(fp)

    # Derive sub-step walkthrough from reads against `.claude/skills/.../steps/*.md`
    # or the orchestrator SKILL.md. Order preserves first-read sequence.
    m.steps_walked = _extract_steps_walked(m.files_read)

    # Categorise produced/updated artefacts under docs/* and state/.
    m.artefacts = _categorise_artefacts(m.files_written + m.files_edited)
    return m


_STEP_FILE_RE = re.compile(
    r"\.claude/skills/(?P<skill>[a-z][a-z0-9-]*)/(?:steps/(?P<step>\d{2}[a-z]?-[a-z0-9-]+)\.md|SKILL\.md)"
)


def _extract_steps_walked(files_read: list[str]) -> list[str]:
    """Return ordered, deduplicated `skill/step` labels for the steps the agent
    actually loaded. Loading the orchestrator SKILL.md is recorded as `skill/SKILL`.
    """
    seen: set[str] = set()
    out: list[str] = []
    for path in files_read:
        m = _STEP_FILE_RE.search(path)
        if not m:
            continue
        skill = m.group("skill")
        step = m.group("step") or "SKILL"
        label = f"{skill}/{step}"
        if label in seen:
            continue
        seen.add(label)
        out.append(label)
    return out


# Path patterns → artefact category. First matching category wins; order matters.
_ARTEFACT_CATEGORIES: list[tuple[str, re.Pattern[str]]] = [
    ("state",             re.compile(r"\docs/state/features\.json$")),
    ("rtm",               re.compile(r"docs/requirements/RTM\.md$")),
    ("story",             re.compile(r"docs/stories/[^/]+\.md$")),
    ("research",          re.compile(r"docs/research/[^/]+\.md$")),
    ("prd",               re.compile(r"docs/features/[^/]+/REQUIREMENTS\.md$")),
    ("plan",              re.compile(r"docs/features/[^/]+/PLAN\.md$")),
    ("validation_report", re.compile(r"docs/features/[^/]+/VALIDATION-[^/]+\.md$")),
    ("review_report",     re.compile(r"docs/features/[^/]+/REVIEW\.md$")),
    ("security_report",   re.compile(r"docs/features/[^/]+/SECURITY-[^/]+\.md$")),
    ("escalation",        re.compile(r"docs/features/[^/]+/ESCALATION\.md$")),
    ("test_cases",        re.compile(r"docs/test-cases/[^/]+\.json$")),
    ("adr",               re.compile(r"docs/adr/[^/]+\.md$")),
    ("session_log",       re.compile(r"docs/sessions/[^/]+\.md$")),
    ("tuning_report",     re.compile(r"docs/tuning/[^/]+\.md$")),
    ("config",            re.compile(r"docs/config/[^/]+\.ya?ml$")),
    ("other_docs",        re.compile(r"docs/[^/]+")),
]


def _categorise_artefacts(files: list[str]) -> dict[str, list[str]]:
    """Filter to artefact files (docs/* and state/), grouped by category.

    Source-code files and config dotfiles are intentionally excluded — the
    dashboard already lists those under "Files written / edited". This view
    surfaces only the SDLC-meaningful artefacts.
    """
    grouped: dict[str, list[str]] = {}
    for fp in files:
        for category, pattern in _ARTEFACT_CATEGORIES:
            if pattern.search(fp):
                bucket = grouped.setdefault(category, [])
                if fp not in bucket:
                    bucket.append(fp)
                break
    return grouped


def _estimate_cost(turns: list[Turn], totals: PhaseMetrics) -> float:
    # Apply sonnet-4-6 rate card only when every assistant turn that has a
    # model is on sonnet 4.6. Mixed-model sessions get cost = 0 (caller can
    # implement a richer rate card later).
    models = {t.model for t in turns if t.role == "assistant" and t.model}
    if models and not all("sonnet-4-6" in m or m.endswith("sonnet-4-6") for m in models):
        return 0.0
    r = _SONNET_46_RATE
    return round(
        (totals.input_tokens * r["input"]
         + totals.output_tokens * r["output"]
         + totals.cache_create_tokens * r["cache_create"]
         + totals.cache_read_tokens * r["cache_read"]) / 1_000_000,
        2,
    )


def fmt_duration(seconds: int) -> str:
    if seconds < 60:
        return f"{seconds}s"
    if seconds < 3600:
        return f"{seconds // 60}m"
    h = seconds // 3600
    m = (seconds % 3600) // 60
    return f"{h}h {m}m" if m else f"{h}h"
